#!/usr/bin/env node
// Builds the extracted Wii disc tree WIT composes into the Dolphin ISO (SPEC §1.5):
//   sys/boot.bin       generated here: ID6, title, Wii magic (never copied from a retail disc)
//   sys/apploader.img  our own apploader (dolphin/apploader/) with the standard 32-byte header
//   sys/main.dol       copied byte-for-byte from boot.dol
//   files/README.txt
// bi2.bin is generated by WIT (region set with --region USA at compose time).
//
//   node mkdisc.mjs <iso-root> <boot.dol> <apploader.bin> <entry-hex> <GAMEID> <title>
import {mkdirSync, readFileSync, writeFileSync, rmSync, copyFileSync} from 'node:fs';
import {join} from 'node:path';

const [root, dol, loader, entryHex, id, title] = process.argv.slice(2);
if (!title || !/^[A-Z0-9]{6}$/.test(id)) { console.error('usage: mkdisc.mjs <iso-root> <boot.dol> <apploader.bin> <entry-hex> <GAMEID> <title>'); process.exit(2); }
rmSync(root, {recursive: true, force: true});
mkdirSync(join(root, 'sys'), {recursive: true});
mkdirSync(join(root, 'files'), {recursive: true});

const boot = Buffer.alloc(0x440);
boot.write(id, 0, 'ascii');            // 0x00 game code + maker
boot[6] = 0;                           // disc number
boot[7] = 0;                           // version
boot.writeUInt32BE(0x5D1C9EA3, 0x18);  // Wii magic
boot.writeUInt32BE(0, 0x1C);           // GameCube magic: none
boot.write(title.slice(0, 63), 0x20, 'ascii');
// 0x420 DOL offset, 0x424 FST offset/size: laid out and patched by WIT when composing.
writeFileSync(join(root, 'sys', 'boot.bin'), boot);

const code = readFileSync(loader);
const padded = Buffer.alloc(Math.ceil(code.length / 32) * 32); code.copy(padded);
const header = Buffer.alloc(32);
header.write('2026/11/15', 0, 'ascii');
header.writeUInt32BE(parseInt(entryHex, 16), 0x10);
header.writeUInt32BE(padded.length, 0x14);
header.writeUInt32BE(0, 0x18);
writeFileSync(join(root, 'sys', 'apploader.img'), Buffer.concat([header, padded]));

// WIT otherwise generates a random title key on every build. Reuse an original,
// WIT-generated homebrew ticket (never taken from a retail disc).
const ticketHex = readFileSync(new URL('../dolphin/generated-ticket.hex', import.meta.url), 'utf8')
  .split('\n').filter(line => !line.startsWith('#')).join('').trim();
const ticket = Buffer.from(ticketHex, 'hex');
if (ticket.length !== 676) throw new Error('homebrew ticket must be 676 bytes');
writeFileSync(join(root, 'ticket.bin'), ticket);
copyFileSync(dol, join(root, 'sys', 'main.dol'));
writeFileSync(join(root, 'files', 'README.txt'),
  'Backyard Cornhole (Wii homebrew). Disc image for Dolphin; the game is sys/main.dol.\n' +
  'Apploader: original code in wii/dolphin/apploader (see wii/dolphin/PROVENANCE.md).\n');
console.log(`disc tree ${root}: ${id} "${title}", apploader ${padded.length} bytes, entry 0x${entryHex}`);
